// Build Visit — определяет визит для результатов.
// Дату берём из trigger-поля document_date (нода "Registrar Labs"), НЕ из $input
// (перед этой нодой стоит Get Visits, его вывод — это строки листа Visits).
// Если визит с такой датой уже есть в книге — переиспользуем его Visit_ID (без дублей).
const t = $('Registrar Labs').first().json;
const existing = $('Get Visits').all().map(i => i.json);

function pd(v){
  var s=String(v==null?'':v).trim().replace(/[\/\-]/g,'.');
  var m=s.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})/); if(m) return {iso:m[3]+'-'+m[2].padStart(2,'0')+'-'+m[1].padStart(2,'0'), ru:m[1].padStart(2,'0')+'.'+m[2].padStart(2,'0')+'.'+m[3]};
  m=s.match(/^(\d{4})\.(\d{1,2})\.(\d{1,2})/); if(m) return {iso:m[1]+'-'+m[2].padStart(2,'0')+'-'+m[3].padStart(2,'0'), ru:m[3].padStart(2,'0')+'.'+m[2].padStart(2,'0')+'.'+m[1]};
  return null;
}

var today = $now.setZone('Asia/Vladivostok');
var p = pd(t.document_date);
if(!p || p.iso > today.toFormat('yyyy-MM-dd')) {
  p = {iso: today.toFormat('yyyy-MM-dd'), ru: today.toFormat('dd.MM.yyyy')};
}

var incLab = (t.lab_name || '').toString().trim();
var incNotes = (t.notes || '').toString().trim();

// ищем существующий визит по совпадению даты
var match = null;
for (var i=0;i<existing.length;i++){
  var ep = pd(existing[i].Date);
  if (ep && ep.iso === p.iso) { match = existing[i]; break; }
}

if (match) {
  return [{ json: {
    Visit_ID: String(match.Visit_ID),
    Date: p.ru,
    Age_at_Visit: (match.Age_at_Visit !== '' && match.Age_at_Visit != null) ? match.Age_at_Visit : (parseInt(p.iso.slice(0,4),10) - 1982),
    Lab_Name: (match.Lab_Name && String(match.Lab_Name).trim()) ? match.Lab_Name : incLab,
    Notes: (match.Notes && String(match.Notes).trim()) ? match.Notes : incNotes,
    _matched_existing: true
  }}];
}

return [{ json: {
  Visit_ID: 'V' + p.iso.replace(/-/g,''),
  Date: p.ru,
  Age_at_Visit: parseInt(p.iso.slice(0,4),10) - 1982,   // год рождения Влада — 1982
  Lab_Name: incLab,
  Notes: incNotes,
  _matched_existing: false
}}];

// Save_Lab_Results → нода "Map".
// Вход: trigger-поля document_date / lab_name / notes / markers_json (JSON-строка массива
// {name,value,unit,ref_low,ref_high}); листы Markers и Visits книги phenoage; результат ноды "Build Visit".
// Выход: строки для листа Results ({Visit_ID,Marker_ID,Value,Original_Unit,Lab_Min,Lab_Max}),
// на каждой строке дублируется _summary для ноды Respond.
// Run Once for All Items.

function safeAll(name) { try { return $(name).all().map(i => i.json); } catch (e) { return []; } }

const trig = (() => {
  try { return $('Registrar Labs').first().json; } catch (e) { return $input.first().json || {}; }
})();
const visit = $('Build Visit').first().json;
const markerRows = safeAll('Get Markers');   // Marker_ID, Name, Category, Standard_Unit, ...

// ---------- нормализация имени показателя ----------
function norm(s) {
  return String(s == null ? '' : s)
    .toLowerCase()
    .replace(/ё/g, 'е')
    .replace(/\([^)]*\)/g, ' ')            // убрать скобки с содержимым
    .replace(/[^a-zа-я0-9%]+/g, ' ')       // оставить буквы/цифры/%
    .replace(/\s+/g, ' ')
    .trim();
}
// свернуть кириллические буквы-двойники в латиницу — чтобы ловить аббревиатуры,
// которые в бланках печатают вперемешку (МСHС, НGB и т.п.)
function fold(s) {
  const m = { 'а': 'a', 'в': 'b', 'е': 'e', 'к': 'k', 'м': 'm', 'н': 'h', 'о': 'o',
    'р': 'p', 'с': 'c', 'т': 't', 'х': 'x', 'у': 'y', 'і': 'i' };
  return String(s || '').replace(/[а-яёі]/g, ch => m[ch] || ch);
}
function toComma(v) {
  if (v == null || v === '') return '';
  return String(v).trim().replace(/\s+/g, '').replace('.', ',');
}
function numOf(v) {
  if (v == null || v === '') return null;
  const n = parseFloat(String(v).replace(/\s+/g, '').replace(',', '.'));
  return isNaN(n) ? null : n;
}

// индекс по названиям из листа Markers
const byName = {};
for (const m of markerRows) {
  if (!m.Marker_ID) continue;
  byName[norm(m.Name)] = m.Marker_ID;
}

// ручной словарь синонимов/аббревиатур -> Marker_ID
const SYN = {
  'билирубин общий': 'M001', 'общий билирубин': 'M001', 'билирубин': 'M001',
  'билирубин прямой': 'M002', 'прямой билирубин': 'M002', 'билирубин конъюгированный': 'M002',
  'глюкоза': 'M003', 'глюкоза плазмы': 'M003', 'глюкоза венозной крови': 'M003', 'глюкоза натощак': 'M003',
  'креатинин': 'M004',
  'мочевая кислота': 'M005',
  'мочевина': 'M006', 'urea': 'M006',
  'общий белок': 'M007', 'белок общий': 'M007',
  'альбумин': 'M008',
  'триглицериды': 'M009', 'тг': 'M009',
  'холестерин общий': 'M010', 'холестерин': 'M010', 'общий холестерин': 'M010', 'холестерин суммарный': 'M010',
  'холестерин лпвп': 'M011', 'лпвп': 'M011', 'hdl': 'M011', 'хс лпвп': 'M011', 'холестерин hdl': 'M011',
  'холестерин лпнп': 'M012', 'лпнп': 'M012', 'ldl': 'M012', 'хс лпнп': 'M012', 'холестерин ldl': 'M012',
  'холестерин лпонп': 'M013', 'лпонп': 'M013', 'vldl': 'M013',
  'холестерин не лпвп': 'M014', 'не hdl': 'M014', 'non hdl': 'M014', 'холестерин неквп': 'M014',
  'аланинаминотрансфераза': 'M015', 'алат': 'M015', 'алт': 'M015', 'alt': 'M015',
  'аспартатаминотрансфераза': 'M016', 'асат': 'M016', 'аст': 'M016', 'ast': 'M016',
  'щелочная фосфатаза': 'M017', 'alp': 'M017', 'щф': 'M017',
  'т4 свободный': 'M018', 'свободный т4': 'M018', 'ft4': 'M018',
  'ттг': 'M019', 'tsh': 'M019', 'тиреотропный гормон': 'M019',
  'тестостерон общий': 'M020', 'тестостерон': 'M020',
  'пса общий': 'M021', 'пса': 'M021', 'psa': 'M021', 'простатический специфический антиген': 'M021',
  'пса свободный': 'M022', 'свободный пса': 'M022',
  'пса свободный пса': 'M023', 'соотношение пса': 'M023',
  'с реактивный белок': 'M024', 'срб': 'M024', 'crp': 'M024', 'hs crp': 'M024', 'вчсрб': 'M024', 'с реактивный белок высокочувствительный': 'M024',
  'ревматоидный фактор': 'M025', 'рф': 'M025',
  'антитела сср': 'M026', 'аццп': 'M026',
  'ферритин': 'M027',
  'железо': 'M028', 'железо сывороточное': 'M028', 'сывороточное железо': 'M028', 'fe': 'M028',
  'натрий': 'M029', 'na': 'M029',
  'калий': 'M030', 'k': 'M030',
  'гликированный гемоглобин': 'M031', 'hba1c': 'M031', 'гликированный гемоглобин hba1c': 'M031', 'гликогемоглобин': 'M031',
  'инсулин': 'M032',
  'фолиевая кислота': 'M033', 'фолаты': 'M033',
  'витамин b12': 'M034', 'b12': 'M034', 'цианокобаламин': 'M034', 'витамин в12': 'M034',
  'витамин d': 'M035', 'витамин d 25 oh': 'M035', 'витамин d 25 он': 'M035', '25 oh витамин d': 'M035', '25 он витамин d': 'M035', 'витамин д': 'M035', '25 гидроксивитамин d': 'M035',
  'ige общий': 'M036', 'ige': 'M036', 'иммуноглобулин e общий': 'M036', 'иммуноглобулин e': 'M036',
  'гемоглобин в кале': 'M037',
  'трансферрин в кале': 'M038',
  'лейкоциты': 'M039', 'wbc': 'M039',
  'эритроциты': 'M040', 'rbc': 'M040',
  'гемоглобин': 'M041', 'hgb': 'M041', 'hb': 'M041',
