// ---------- нормализация имени показателя ----------
function norm(s) {
  return String(s == null ? '' : s)
    .toLowerCase()
    .replace(/ё/g, 'е')
    .replace(/\([^)]*\)/g, ' ')            // убрать скобки с содержимым
    .replace(/[^a-zа-я0-9%]+/g, ' ')       // оставить буквы/цифры/%
    .replace(/\s+/g, ' ')
    .trim();
}
// свернуть кириллические буквы-двойники в латиницу — чтобы ловить аббревиатуры,
// которые в бланках печатают вперемешку (МСHС, НGB и т.п.)
function fold(s) {
  const m = { 'а': 'a', 'в': 'b', 'е': 'e', 'к': 'k', 'м': 'm', 'н': 'h', 'о': 'o',
    'р': 'p', 'с': 'c', 'т': 't', 'х': 'x', 'у': 'y', 'і': 'i' };
  return String(s || '').replace(/[а-яёі]/g, ch => m[ch] || ch);
}
function toComma(v) {
  if (v == null || v === '') return '';
  return String(v).trim().replace(/\s+/g, '').replace('.', ',');
}
function numOf(v) {
  if (v == null || v === '') return null;
  const n = parseFloat(String(v).replace(/\s+/g, '').replace(',', '.'));
  return isNaN(n) ? null : n;
}

