// пары «% <-> абс» для 5-компонентной лейкоформулы.
// В SYN голое имя («нейтрофилы») ведёт на %-вариант; здесь выбираем по единице измерения.
const PCT_TO_ABS = { M059: 'M058', M062: 'M061', M064: 'M063', M066: 'M065', M068: 'M067' };
const ABS_SET = new Set(['M058', 'M061', 'M063', 'M065', 'M067']);

function unitIsPct(u) { return u === '%' || /процент|отн\b/.test(u); }
function unitIsAbs(u) {
  return /10\s*\^?\s*9|10\s*\*\s*9|10\s*9|кл\/мкл|g\/l|10\^9\/л|абс|x10/.test(u) || /\/\s*л$/.test(u);
}

// латинские аббревиатуры (точное совпадение целиком, после fold)
const ABBR = {
  mchc: 'M045', mch: 'M044', mcv: 'M043', wbc: 'M039', rbc: 'M040', hgb: 'M041', hb: 'M041',
  hct: 'M042', plt: 'M046', rdw: 'M049', rdwcv: 'M049', rdwsd: 'M050', mpv: 'M052', pdw: 'M051',
  pct: 'M053', esr: 'M048', soe: 'M048', alt: 'M015', ast: 'M016', alp: 'M017', tsh: 'M019',
  ft4: 'M018', psa: 'M021', crp: 'M024', hscrp: 'M024', hba1c: 'M031', inr: 'M073', pti: 'M077',
  aptt: 'M069', neu: 'M059', lym: 'M062', mono: 'M064', eos: 'M066', baso: 'M068',
};

function resolveId(name, unit) {
  const n = norm(name);
  const nf = fold(n);
  const u = norm(unit);
  let id = SYN[n] || byName[n] || SYN[nf] || byName[nf] || null;
  if (!id) {
    const flat = nf.replace(/[\s-]/g, '');
    if (ABBR[flat]) id = ABBR[flat];
  }
  if (!id) {
    for (const k of Object.keys(SYN)) {
      if (k.length >= 4 && n.indexOf(k) === 0) { id = SYN[k]; break; }
    }
  }
  if (!id) return null;
  // лейкоформула: имя в тексте может уже нести «абс»/«%», иначе решаем по единице
  if (/\bабс/.test(n)) { for (const [p, a] of Object.entries(PCT_TO_ABS)) if (id === p) id = a; }
  else if (/\bотн|%/.test(n)) { /* оставляем %-вариант */ }
  else if (PCT_TO_ABS[id]) {
    if (unitIsAbs(u) && !unitIsPct(u)) id = PCT_TO_ABS[id];   // -> абс
  }
  // если по имени попали в абс-вариант, но единица — процент, вернуть %
  if (ABS_SET.has(id) && unitIsPct(u)) {
    for (const [p, a] of Object.entries(PCT_TO_ABS)) if (a === id) id = p;
  }
  return id;
}

// ---------- конвертация единиц для маркеров PhenoAge ----------
// PhenoAge-формула чувствительна к единицам. Приводим 4 «опасных» маркера к стандартной.
// Возвращает {value, unit, converted} или null (оставить как есть).
function convUnit(id, value, unit) {
  const u = norm(unit).replace(/\s/g, '');                 // остаются только буквы/цифры/%
  const isGdl = /(gdl|гдл)/.test(u);                       // g/dl
  const isMgdl = /(mgdl|мгдл)/.test(u);                    // mg/dl
  if (id === 'M008' && isGdl) return { value: value * 10, unit: 'г/л', note: 'из г/дл' };            // альбумин
  if (id === 'M003' && isMgdl) return { value: value / 18.0, unit: 'ммоль/л', note: 'из мг/дл' };    // глюкоза
  if (id === 'M004' && isMgdl) return { value: value * 88.4, unit: 'мкмоль/л', note: 'из мг/дл' };   // креатинин
  if (id === 'M024' && isMgdl) return { value: value * 10, unit: 'мг/л', note: 'из мг/дл' };         // СРБ
  return null;
}

// ---------- разбор входного массива ----------
let raw = trig.markers_json;
let list = [];
try {
  if (Array.isArray(raw)) list = raw;
  else if (typeof raw === 'string' && raw.trim()) list = JSON.parse(raw);
  else if (raw && typeof raw === 'object') list = raw.markers || [];
} catch (e) { list = []; }

const vid = visit.Visit_ID;
const seen = new Set();
const rows = [];
const matched = [];
const unmatched = [];
const converted = [];

for (const it of list) {
  if (!it) continue;
  const name = it.name || it.Name || it.marker || it.title || '';
  const valRaw = it.value != null ? it.value : (it.Value != null ? it.Value : it.result);
  if (!name || valRaw == null || String(valRaw).trim() === '') continue;
  if (numOf(valRaw) == null) continue; // «отрицательно», «не обнаружено» и т.п. — пропускаем
  const unit = it.unit || it.Unit || it.units || '';
  const id = resolveId(name, unit);
  if (!id) { unmatched.push(String(name).trim()); continue; }
  if (seen.has(id)) continue;
  seen.add(id);

  let outVal = toComma(valRaw);
  let outUnit = String(unit || '').trim();
  const c = convUnit(id, numOf(valRaw), unit);
  if (c) {
    outVal = toComma(Math.round(c.value * 1000) / 1000);
    outUnit = c.unit + ' (' + (String(unit || '').trim() || c.note) + ')';
    converted.push(name + ' ' + c.note);
  }

  rows.push({
    Visit_ID: vid,
    Marker_ID: id,
    Value: outVal,
    Original_Unit: outUnit,
    Lab_Min: toComma(it.ref_low != null ? it.ref_low : it.refLow != null ? it.refLow : it.min),
    Lab_Max: toComma(it.ref_high != null ? it.ref_high : it.refHigh != null ? it.refHigh : it.max),
  });
  matched.push(id);
}

let summary;
if (rows.length) {
  summary = 'Лабораторные результаты сохранены: визит ' + vid + ' (' + visit.Date + ', ' +
    (visit.Lab_Name || 'лаборатория не указана') + '), показателей записано: ' + rows.length + '.';
  if (converted.length) summary += ' Приведены к стандартным единицам: ' + converted.join('; ') + '.';
  if (unmatched.length) summary += ' Не распознаны и НЕ записаны в структуру: ' + unmatched.join('; ') + '.';
} else {
  summary = 'Структурные показатели не сохранены: ' +
    (list.length ? 'ни одно из названий не распознано (' + unmatched.join('; ') + ')' :
      'в вызове не передан массив показателей') + '. Клиническая сводка в медкарте не затронута.';
  rows.push({ Visit_ID: vid, Marker_ID: '_none', Value: '', Original_Unit: '', Lab_Min: '', Lab_Max: '' });
}

return rows.map(r => ({ json: { ...r, _summary: summary } }));
